using System;
namespace Downfield {
public partial class Simulation {
 void KnockDown(Player player,float x,float z,float force){ReleaseBlock(player);float length=(float)Math.Sqrt(x*x+z*z);if(length<.1f){x=0;z=player.Team==1?1:-1;length=1;}player.KnockVX=x/length*force;player.KnockVZ=z/length*force;player.ImpactLevel=force>=19?2:force>=13?1:0;player.KnockTime=player.KnockDuration=player.ImpactLevel>=2?1.2f:.95f;player.Blocked=player.KnockDuration+.15f;player.Pose="knockdown";player.PoseTime=.95f;player.VX=player.KnockVX;player.VZ=player.KnockVZ;}
 void UpdateKnockbacks(float dt){foreach(Player p in Players)if(p.KnockTime>0){p.KnockTime=Math.Max(0,p.KnockTime-dt);p.X+=p.KnockVX*dt;p.Z+=p.KnockVZ*dt;float damping=(float)Math.Exp(-dt*(p.ImpactLevel>=2?3.2f:5));p.KnockVX*=damping;p.KnockVZ*=damping;p.Pose="knockdown";p.PoseTime=Math.Max(p.PoseTime,p.KnockTime);if(p.KnockTime<=0){p.KnockVX=p.KnockVZ=p.VX=p.VZ=0;p.Pose="idle";}}}
 void TruckImpact(Player defender,bool won){BigHits++;Cue("truck");Cue("crowd_big");HitX=Controlled.X;HitZ=Controlled.Z;HitFlash=.95f;HitLabel=won?"TRUCKED!":"TRUCK STUFFED!";if(won){float dx=defender.X-Controlled.X,dz=defender.Z-Controlled.Z;if(Distance(0,0,Controlled.VX,Controlled.VZ)>1){dx=Controlled.VX;dz=Controlled.VZ;}bool huge=Controlled.Power>=88||Sprint;KnockDown(defender,dx,dz,huge?22:15.5f);ImpactPower=huge?2:1;if(huge){SpectacularHits++;HitFlash=1.2f;HitLabel="SENT FLYING!";Cue("slam");Cue("crowd_cheer");}TryInjury(defender,false);Controlled.VX*=.65f;Controlled.VZ*=.65f;Message="TRUCKED / KEEP RUNNING";}else{bool huge=Sprint||defender.Power>=Controlled.Power+8;KnockDown(Controlled,Controlled.X-defender.X,Controlled.Z-defender.Z,huge?21:15);ImpactPower=huge?2:1;if(huge){SpectacularHits++;HitFlash=1.2f;HitLabel="DENIED!";Cue("slam");}Message="TRUCK STUFFED";}skillTime=0;}
}
}
